{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "The polar, ionizable piperidine alcohol [18F]FEP-4MOH showed very low brain uptake (<0.05% dose/g) after IV dosing in rat; as the closest polar-amine phenotype, it supports poor CNS access for the dicationic guanidine-azocane query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Compound 4g, a piperidine-containing polar molecule, had log BB -0.77 after oral dosing in rats, showing brain exposure far below plasma; this supports limited CNS access despite a basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Compound 4f similarly gave log BB -0.57 in rats, reinforcing that piperidine-containing polar molecules can have poor brain partitioning.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Raloxifene, a large polar molecule, had brain concentration about 1/100 of blood, illustrating that polar/large structures can have very limited CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "NY0128, a guanidine-containing compound, crossed the BBB and accumulated in rat brain, but its bulky triphenylmethyl ether provides lipophilicity absent in the dicationic query, so transfer is limited.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "A zwitterionic amino acid piperidine was reported to cross the BBB in humans, but it lacks the dicationic guanidine-azocane core, limiting transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pitolisant, a lipophilic basic amine, crosses the BBB, but its aromatic/lipophilic character and monobasic nature are not representative of the dicationic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ro 03-8799 achieved 23% CSF/plasma in a human sample, showing some polar piperidine compounds can access CSF, but it is not dicationic and has a nitroimidazole moiety, limiting transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Piracetam, a small polar amide, achieved measurable CSF AUC in rats, showing some polar molecules can access CSF; however, it is neutral and much smaller than the dicationic query, so transfer is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is guanethidine, a dicationic guanidine-azocane with essentially no neutral fraction and very low logD at pH 7.4. Direct evidence from the closest polar ionized amine (C09) shows very low brain uptake, and new log BB data for polar piperidine-containing compounds (C15, C22) and raloxifene (C14) support limited CNS access. The many BBB-penetrant basic amines (biperiden, pitolisant, [11C]1, Ro 03-8799) are lipophilic, monobasic, or contain large hydrophobic groups and are not representative of the dicationic query. Therefore the molecule is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct BBB/PK measurement for guanethidine itself in the provided evidence set.",
    "All evidence analogues have low Morgan similarity to the query.",
    "No efflux transporter or active-uptake assay data are available for the query.",
    "No human CSF or brain concentration data are available for the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C15", "C22"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "polyphenolic piperidine ethers"
    },
    {
      "applicability": "low",
      "card_ids": ["C12", "C11", "C20"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "biperiden"
    },
    {
      "applicability": "low",
      "card_ids": ["C21", "C13"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "H3 antagonist radiotracers"
    },
    {
      "applicability": "low",
      "card_ids": ["C16"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "nitroimidazole piperidine"
    },
    {
      "applicability": "low",
      "card_ids": ["C14"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "raloxifene"
    },
    {
      "applicability": "low",
      "card_ids": ["C17", "C18"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "piracetam"
    },
    {
      "applicability": "low",
      "card_ids": ["C19"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "pitolisant"
    }
  ],
  "revision_action": "strengthen"
}

